import { useEffect, useState } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";

export default function Dashboard() {
  const [units, setUnits] = useState([]);

  const [selectedUnit, setSelectedUnit] = useState(null);
  const [startDate, setStartDate] = useState("");
  const [endDate, setEndDate] = useState("");
  const [totalCost, setTotalCost] = useState(0);

  const navigate = useNavigate();

  const userInfo = JSON.parse(localStorage.getItem("userInfo"));
  const token = userInfo?.token;

  // ✅ Fetch units
  useEffect(() => {
    const fetchUnits = async () => {
      try {
        const { data } = await axios.get(
          "http://localhost:5001/api/units"
        );
        setUnits(data);
      } catch (error) {
        console.error(error);
      }
    };

    fetchUnits();
  }, []);

  // ✅ Calculate total cost (FIXED VERSION)
  useEffect(() => {
    if (startDate && endDate && selectedUnit) {
      const start = new Date(startDate);
      const end = new Date(endDate);

      // ✅ normalize time
      start.setHours(0, 0, 0, 0);
      end.setHours(0, 0, 0, 0);

      const diffTime = end - start;
      const diffDays = Math.floor(diffTime / (1000 * 60 * 60 * 24)) + 1;

      if (diffDays > 0) {
        setTotalCost(diffDays * selectedUnit.pricePerDay);
      } else {
        setTotalCost(0);
      }
    }
  }, [startDate, endDate, selectedUnit]);

  // ✅ Confirm booking (FIXED)
  const handleConfirmBooking = async () => {
    try {
      const { data } = await axios.post(
        "http://localhost:5001/api/bookings",
        {
          unitId: selectedUnit._id,
          startDate,
          endDate,
          totalCost,
        },
        {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        }
      );

      // ✅ Redirect to checkout
      navigate(`/checkout/${data._id}`);

      // ✅ Reset
      setSelectedUnit(null);
      setStartDate("");
      setEndDate("");

    } catch (error) {
      alert("Booking failed");
    }
  };

  return (
    <div style={{ padding: "30px", background: "#F3F4F6", minHeight: "100vh" }}>
      <h2 style={{ marginBottom: "20px" }}>Available Storage Units</h2>

      {units.length === 0 && <p>No units available.</p>}

      {/* ✅ GRID */}
      <div
        style={{
          display: "grid",
          gridTemplateColumns: "repeat(auto-fill, minmax(280px, 1fr))",
          gap: "20px",
        }}
      >
        {units.map((unit) => (
          <div key={unit._id} style={card}>
            <h3>{unit.name}</h3>
            <p><strong>Size:</strong> {unit.size}</p>
            <p><strong>Price:</strong> ${unit.pricePerDay}/day</p>

            <p>{unit.available ? "✅ Available" : "❌ Booked"}</p>

            {unit.available && (
              <button style={bookBtn} onClick={() => setSelectedUnit(unit)}>
                Book Now
              </button>
            )}
          </div>
        ))}
      </div>

      {/* ✅ BOOKING MODAL */}
      {selectedUnit && (
        <div style={overlay}>
          <div style={modal}>
            <h3>Book {selectedUnit.name}</h3>

            <label>Start Date</label>
            <input
              type="date"
              value={startDate}
              onChange={(e) => setStartDate(e.target.value)}
              style={input}
            />

            <label>End Date</label>
            <input
              type="date"
              value={endDate}
              onChange={(e) => setEndDate(e.target.value)}
              style={input}
            />

            <p><strong>Total Cost:</strong> ${totalCost}</p>

            <button style={primaryBtn} onClick={handleConfirmBooking}>
              Confirm Booking
            </button>

            <button
              style={cancelBtn}
              onClick={() => {
                setSelectedUnit(null);
                setStartDate("");
                setEndDate("");
              }}
            >
              Cancel
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

const card = {
  background: "white",
  padding: "20px",
  borderRadius: "10px",
  boxShadow: "0 4px 10px rgba(0,0,0,0.1)"
};

const bookBtn = {
  marginTop: "10px",
  background: "#2563EB",
  color: "white",
  padding: "10px",
  width: "100%",
  border: "none",
  borderRadius: "6px"
};

const overlay = {
  position: "fixed",
  top: 0,
  left: 0,
  width: "100%",
  height: "100%",
  background: "rgba(0,0,0,0.5)",
  display: "flex",
  justifyContent: "center",
  alignItems: "center"
};

const modal = {
  background: "white",
  padding: "25px",
  borderRadius: "10px",
  width: "320px",
  display: "flex",
  flexDirection: "column",
  gap: "10px"
};

const input = {
  padding: "8px",
  borderRadius: "5px",
  border: "1px solid #ddd"
};

const primaryBtn = {
  background: "#2563EB",
  color: "white",
  padding: "10px",
  border: "none",
  borderRadius: "5px"
};

const cancelBtn = {
  padding: "8px",
  border: "none",
  background: "#ddd",
  borderRadius: "5px"
};
